INSERT INTO items (item_key,name,description,item_type,rarity,weight,value_gp,damage_dice,damage_type,armor_bonus,armor_type,slot,properties,image_url,icon) VALUES
('almoners_list','The Almoner''s List','Who in Rivermark is being fed by the parish, kept in a hand that gets smaller down the page to save paper. Eighty-one names. Forty of them were added in the last eight months, and thirty-six of those forty gave a holding west of the river as their last address.','misc','common',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('amulet_of_warding','Amulet of Warding','A river-stone drilled and strung on waxed cord, carved with the Priory''s oldest mark. What reaches for the wearer reaches a little short.','misc','uncommon',0.2,300,NULL,NULL,NULL,NULL,'amulet','{"save_bonus":1}',NULL,'treasure'),
('antitoxin','Antitoxin','A cloudy phial of crushed charcoal and fen herbs. Drunk before a fight turns bad, it steadies the blood against poison for a while.','misc','common',0.1,40,NULL,NULL,NULL,NULL,NULL,'{"use_effect":{"boon":{"save_advantage_vs":"poison"},"rounds":10}}',NULL,'potion'),
('anvil_note','The Anvil Note','Eighty gold lent against a forge in the fourth year of the road tax, signed by Brenna Coalwright and by a cooper who has been dead since. On the back, four assignments in four different hands, each one selling the debt on. The last hand did not sign a name, only a house.','misc','uncommon',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('arch_rubbing','Charcoal Rubbing','Paper laid on brick and rubbed with the side of a charcoal. It has taken the cut cleanly: a plumb-line crossed by a square, no larger than a thumbnail, cut before the brick was fired.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('boom_forge_gauge','The Unmarked Gauge','A gauge from the Boom Forge''s fifth hearth: a hand''s length of iron with two notches and no League stamp, no maker''s mark and no date, which is three things a gauge is never without. What it gauges is not chain. It is the throat of an anchor a good deal heavier than anything in this harbour needs.','misc','uncommon',2,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'tools'),
('caulkers_maul','Caulker''s Maul','A shipwright''s beetle rehafted for a fight: two-handed, elm-headed, iron-banded at both ends, and heavy in a way that stops mattering after the first swing and starts mattering a great deal after the tenth.','weapon','common',10,10,'2d6','bludgeoning',NULL,NULL,NULL,'{"two_handed":true,"heavy":true,"martial":true}',NULL,'mace'),
('chain_shirt','Chain Shirt','Rings under a leather shell. Warden issue, twenty years out of date.','armor','common',20,50,NULL,NULL,13,'medium',NULL,'{"dex_bonus":true,"dex_bonus_max":2}',NULL,'armor'),
('charter_ledger','The Quiet Charter''s Book','A ledger in nine hands, ruled in three columns — in, out, and paid — with no names in any of them, only marks. It balances. Whoever keeps it is better at this than anybody in the Wet Hall, and has been doing it for six years, and has never once written a word that could be read aloud in a court.','misc','rare',1.5,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('cloak_of_the_marsh','Cloak of the Marsh','Waxed wool the colour of standing water, lined with fen-moss that never dries out. The bog''s own venoms slide off it.','misc','uncommon',3,350,NULL,NULL,NULL,NULL,'cloak','{"resistance":["poison"]}',NULL,'armor'),
('corse_retainer','Articles of Retainer','Two sheets, signed, sealed and entirely lawful, engaging the bearer at forty gold a quarter for services not further described. It is written in a clerk''s hand and it is written kindly. There is no clause about ending it, because nobody has ever asked for one.','misc','uncommon',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('court_slate','Court Slate','A palm of roofing slate with a notch filed in one edge and a hole drilled in the other. It means the Low Court has had its business with you and closed the book. Down there it is worth more than money, and up here it is worth nothing at all, which is roughly the whole of Undertown''s opinion of Rivermark.','misc','uncommon',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"safe_passage":"undertown"}',NULL,'amulet'),
('culms_return','The Factor''s Return','Eleven months of quarterly returns to Lathmere in Bevis Culm''s small upright hand, each one declaring the granary''s holding, each one wrong by the same growing margin. The first is wrong by two weeks. The last is wrong by nine. Nothing in the arithmetic is careless.','misc','rare',0.4,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('dart','Dart','Weighted, finger-length, sold by the handful. Quicker to throw than to explain.','weapon','common',0.25,1,'1d4','piercing',NULL,NULL,NULL,'{"thrown":"20/60","finesse":true,"simple":true}',NULL,'weapon'),
('deepworks_lamp','Caged Shaft Lamp','A brass lamp inside a gauze cage, issued against a peg number and returned at the end of shift. It burns eleven hours, it will not fire a gas seam, and it has somebody else''s number scratched off the base.','misc','common',3,18,NULL,NULL,NULL,NULL,NULL,'{"light":true}',NULL,'lantern'),
('dried_fen_root','Dried Fen-Root','A hand of black root, split and dried over smoke, tied with grass. It smells of iron and low water. Osric Fen will pay for it and will not say what he wants it for, which is not the same as not knowing.','misc','uncommon',1,25,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'potion'),
('drovers_staff','Drover''s Ash Staff','Six feet of seasoned ash with an iron ferrule and a hook, cut for turning cattle and used for other things on the road at night. Balanced nearer the top than a walking staff, which tells you what it is for.','weapon','common',4,30,'1d6','bludgeoning',NULL,NULL,NULL,'{"versatile":"1d8","reach":true}',NULL,'staff'),
('fen_root_bundle','Cut Fen-Root','A bundle of pale jointed root, still wet, tied at both ends. It smells of bruised iron. It has to be cut in water and dried out of the sun or it is worth nothing, which is most of why nobody in Rivermark grows it.','misc','common',3,45,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'herb'),
('fen_waders','Fen-Wardens'' Waders','Greased hide to the thigh, laced at the calf so they can be cut off in a hurry, with a knife-pocket on the outside of the right leg. Made for standing in cold water all day and getting out of it faster than that.','armor','uncommon',4,90,NULL,NULL,0,'boots',NULL,'{"no_difficult_terrain_marsh":true}',NULL,'boots'),
('fennow_ledger','The Fennow Deposit Book','Waterlogged to the spine and legible anyway, because it was written in oak-gall ink by people who expected to be checked. Two hundred and six names, what each of them put in the strongroom, and the date the doors were shut on all of it. The last eleven entries are all one week, and all withdrawals, and all to the bank''s own partners.','misc','rare',4,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('ford_record_copy','The Ford Entry, Fair Copy','Eleven lines copied out of the priory''s own record of the fourth winter: the brothers who went down to the crossing, the count of the dead, the order given for the huts, and the name of the brother who would not carry it out. It does not use the word the order uses now.','misc','rare',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('gate_wheel_key','Gate Wheel Key','A square iron key eighteen inches long, for the worm-screw on the flood gate. Without it the wheel spins free and the gate does whatever it was last told to do. There were two. This is one.','misc','uncommon',4,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'tools'),
('grain_tally','Stamped Tally Stick','A split hazel stick notched for eighteen sacks, stamped with the granary reeve''s mark.','misc','common',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'scroll'),
('greataxe','Greataxe','A heavy two-handed axe.','weapon','common',7,30,'1d12','slashing',NULL,NULL,NULL,'{"heavy":true,"two_handed":true,"martial":true}',NULL,'axe'),
('grey_road_cloak','Grey Road Oilcloth','Warden-cut, waxed to the colour of wet pine, with the shoulders doubled where a pack rides and a pocket inside the breast exactly the size of a folded list. It has come eighty-five miles through the Wyrdpines with somebody inside it and it has not let the weather in yet.','armor','uncommon',3,140,NULL,NULL,0,'cloak',NULL,'{"stealth_advantage_outdoors":true}',NULL,'cloak'),
('halberd','Halberd','An axe, a spike and a hook on six feet of pole. It keeps people at arm''s length and then some.','weapon','common',6,20,'1d10','slashing',NULL,NULL,NULL,'{"reach":true,"heavy":true,"two_handed":true,"martial":true}',NULL,'weapon'),
('harrow_letters','Four Letters to Sten Harrow','Four offers for one farm, over nine months, each better than the last. Three are in a clerk''s hand and the fourth is in a different one. None of them are signed with a name. All four are sealed with a black wax square, and the offer is not for the land — it is for the water right on the mill race.','misc','uncommon',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('holy_symbol','Pewter Sun-Disc','A cheap pewter disc on a cord. The order that issued it has asked for it back twice.','misc','common',1,5,NULL,NULL,NULL,NULL,NULL,'{"focus":"divine"}',NULL,'amulet'),
('indenture_paper','Corrin Dale''s Indenture','Three years'' labour against a cottage, a cow and the carriage of both, with the reckoning of days to be kept by the works and the reckoning to be final. Every clause in it is fair. The unfairness is entirely in the arithmetic, and the arithmetic is on the other sheet, which he has never been given.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('javelin','Javelin','A light spear balanced for throwing, with a soft iron neck that bends on impact.','weapon','common',2,5,'1d6','piercing',NULL,NULL,NULL,'{"thrown":"30/120","simple":true}',NULL,'weapon'),
('lading_bill','Bill of Lading','Twelve hundredweight of coarse salt, carriage paid at Greyhythe, to be delivered to Rivermark quay and invoiced to the consignee. The consignee is named in a clerk''s copperplate. Nobody in Rivermark has ever heard of him, and the quay master''s book has the same name on eleven other bills going back to spring.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('league_standard_weight','The League Standard Weight','A cylinder of cast bronze the size of a loaf, stamped with the Mere and the League''s arms and a date forty-one years old, and kept in a sealed box with three locks because everything in this city is weighed against it. Set it on a true beam and it comes up four ounces light. The filing is on the underside, where the stamp is, and it is not new.','misc','rare',14,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'treasure'),
('leather_armor','Leather Armor','Boiled hide. Quiet, and cheap to replace.','armor','common',10,10,NULL,NULL,11,'light',NULL,'{"dex_bonus":true}',NULL,'armor'),
('light_crossbow','Light Crossbow','Steel prod, walnut stock. Slower than a bow and forgiving of a shaking hand.','weapon','common',5,25,'1d8','piercing',NULL,NULL,NULL,'{"ranged":"80/320","two_handed":true,"loading":true,"simple":true}',NULL,'bow'),
('longbow','Longbow','A stave taller than the archer, of laminated yew. It wants a strong back.','weapon','common',1,50,'1d8','piercing',NULL,NULL,NULL,'{"ranged":"150/600","two_handed":true,"heavy":true,"martial":true}',NULL,'bow'),
('longsword','Longsword','A versatile martial blade favoured by fighters.','weapon','common',3,15,'1d8','slashing',NULL,NULL,NULL,'{"versatile":"1d10","martial":true}',NULL,'sword'),
('longsword_fine','Longsword +1','Old City steel, older than the drowning, and it has not taken a nick since. The balance does half the work of the swing.','weapon','rare',3,500,'1d8','slashing',NULL,NULL,NULL,'{"versatile":"1d10","attack_bonus":1,"damage_bonus":1}',NULL,'weapon'),
('mace','Mace','Plain iron head on an ash haft. Aldric has never called it a weapon.','weapon','common',4,5,'1d6','bludgeoning',NULL,NULL,NULL,'{"simple":true}',NULL,'mace'),
('marked_pauldron','The Left Pauldron','A shoulder-piece of good human plate, sized for a big man and worn by somebody a third his weight. The straps have been shortened three times. Punched into the lining plate where nobody would look is a small clean mark: a plumb-line and a square.','armor','uncommon',6,60,NULL,NULL,0,'shoulder',NULL,'{"quest_item":true}',NULL,'armor'),
('mearing_rubbing','Rubbing from the Mearing Stone','Charcoal on paper, taken off the fourth face of the boundary stone. The old marks came out faint. The new cutting came out sharp: a plumb-line and a square, and no letters at all.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('mere_token','An Offering That Came Back','A fisherman''s copper luck-piece with a hole drilled through it, thrown off the temple rail into forty fathoms and found four days later on the shingle, dry. It is not weathered. It is not corroded. It is a little warmer than the hand that holds it, and it stays that way.','misc','rare',0.1,0,NULL,NULL,NULL,NULL,'amulet','{"save_bonus":1}',NULL,'amulet'),
('oil_of_embers','Oil of Embers','A stoppered flask of pitch that never quite goes out. Worked along a blade mid-fight, every blow lands burning for a while.','misc','uncommon',1,60,NULL,NULL,NULL,NULL,NULL,'{"use_effect":{"boon":{"on_hit":"1d4 fire"},"rounds":10}}',NULL,'potion'),
('oilskin_hood','Drainman''s Oilskin','A hooded cape of waxed canvas, stiff as board and proof against anything that falls. The nightmen wear them and nobody else will, because of what the wearing of one says about your week.','armor','common',4,15,NULL,NULL,0,'cloak',NULL,'{"quiet_underground":true}',NULL,'cloak'),
('oldcity_boys_shoe','A Child''s Shoe','One of a great many, in a wide ring around a cauldron. This one has a name inked inside the tongue by somebody who expected it to come home.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'misc'),
('oldcity_crystal_bowl','The Crystal Bowl','Wrapped in three separate cloths inside a velvet-lined sack, and worth more than everything wrapped alongside it put together. It has come down a chimney chute and through two burglaries without a chip, which cannot go on for ever.','treasure','rare',4,100,NULL,NULL,NULL,NULL,NULL,'{"fragile":true}',NULL,'gem'),
('oldcity_cut_gems','The Cutter''s Finished Work','Nine stones at thirty gold, five at a hundred, and two that are worth three hundred each and know it. Set into the plaster of the workshop wall at chest height, because that is where you hid things when the ceiling was the thing you did not trust.','treasure','uncommon',1,1250,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gem'),
('oldcity_dagger_of_the_warren','Jimmy''s Dagger','A plain blade with an unhelpful history and a maker''s mark nobody recognises. It bites truer than it has any business biting, and against goblinkind it bites a great deal truer than that — which suggests the mark belonged to somebody with a specific grievance.','weapon','uncommon',1,350,'1d4+1','piercing',NULL,NULL,NULL,'{"finesse":true,"light":true,"thrown":true,"attack_bonus":1,"damage_bonus":1,"bane":{"type":"humanoid (goblinoid)","attack_bonus":2,"damage_bonus":2}}',NULL,'dagger'),
('oldcity_engineers_tally','The Engineers'' Tally Board','Loads of dressed stone in, loads of dressed stone out, ruled in two neat columns by somebody who rules neat columns. The columns do not agree, and the difference has been going one way for eleven weeks.','misc','common',2,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('oldcity_gang_chest','The Gang''s Chest','Six hundred copper, three hundred and thirty silver, ninety gold, under a pair of floorboards that lift together. There is one key and Jimmy Able has it.','treasure','common',30,126,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'coin'),
('oldcity_lockbox_purse','The Renegade''s Purse','Thirty gold in a lockbox a dead man would not let go of. He got further with it than the others expected and not nearly as far as he did.','treasure','common',1,30,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'coin'),
('oldcity_old_coin','Old City Coin','Four thousand silver pieces of a mint nobody has struck in three hundred years, in a strongbox under a workbench. The faces are all the same man and none of the dates agree.','treasure','common',20,400,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'coin'),
('oldcity_serviceable_mail','Serviceable Mail','Off one of the dusty ones, and better kept than the man who last wore it. Whatever came for him did not come through the mail.','armor','common',55,35,NULL,NULL,6,'heavy',NULL,NULL,NULL,'armor'),
('oldcity_silver_ring','Silver Ring','Off a hand that has been in the webbing long enough to have gone to leather. Plain, worn thin on the inside, the kind of ring somebody was given rather than bought.','treasure','common',0,20,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ring'),
('oldcity_silver_service','Burgled Silver','A dozen pieces of household silver, each wrapped separately and none of them from the same household. Plates, a pair of goblets, cutlery settings with three different monograms. Somewhere up in the City twelve people have reported the same night.','treasure','common',12,90,NULL,NULL,NULL,NULL,NULL,'{"stolen":true}',NULL,'coin'),
('oldcity_steel_helm','Dented Steel Helm','The gleam that draws people further into the web than they meant to go. Still on its owner when you find it, and its owner is past objecting.','armor','common',6,10,NULL,NULL,0,'helm',NULL,NULL,NULL,'helmet'),
('oldcity_uncut_stones','Tray of Uncut Stones','Thirty rough stones in a graded wooden tray, sorted smallest to largest by a hand that did it every evening. Uncut they are worth perhaps ten gold apiece. Cut, by somebody who knows how, they would be worth a great deal more.','treasure','common',3,300,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'gem'),
('oldcity_wand_of_secrets','Wand of Detecting Secrets','A slim rod of blackened rowan with thirty-one notches filed into the grip and no thirty-second. Held out at arm''s length in a dark place it grows perceptibly warmer when pointed at a way somebody meant to be missed. It does not say what kind of way, or what is behind it.','misc','uncommon',1,400,NULL,NULL,NULL,NULL,NULL,'{"quest_item":false,"attunement":false,"charges":31,"effect":"reveals_hidden_exits"}',NULL,'wand'),
('oldcity_warg_collar','Spiked Collar of the Warg','Heavy leather, iron-spiked, and cut on the inside face with a design that will not stay in the eye — the lines seem to have been done in the wrong order. Whatever it was made to keep off, it kept off. The warg that wore it was not the thing being protected.','misc','uncommon',3,120,NULL,NULL,NULL,NULL,NULL,'{"quest_item":false,"cursed_looking":true}',NULL,'amulet'),
('pilots_glass','Vennik''s Long Glass','Four draws of lacquered brass and Lathmere lenses, made for reading a shoal at two miles and a face at four hundred paces. Vennik grinds his own glass and will tell you at length why the third element is the one that matters.','misc','uncommon',2,180,NULL,NULL,NULL,NULL,NULL,'{"perception_advantage_distant":true}',NULL,'tools'),
('pit_belt','The Pit Belt','Three inches of harness leather with the names of eleven winners punched into it in a line, and room punched for a twelfth. It is worth nothing and the crowd knows exactly what it is worth.','treasure','uncommon',2,25,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'belt'),
('pit_bond','A Bond of Service','Forty-one gold advanced against eighteen months of bouts, at a rate of forfeit that means the eighteen months have quietly become four years. Lawful, signed, and witnessed by two people who were paid to witness it.','misc','uncommon',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('pit_wardens_coat','Pit Warden''s Coat','Doubled canvas over a lining of small plates, cut long, with the collar high against falling grit. Company issue and company quality — which is to say better than the watch wears, and paid for out of a different book.','armor','uncommon',12,150,NULL,NULL,13,'light',NULL,'{"dex_bonus":true}',NULL,'armor'),
('potion_healing','Potion of Healing','A red liquid that glimmers when agitated. Restores 2d4+2 hit points.','potion','common',0.5,50,NULL,NULL,NULL,NULL,NULL,'{"heals":"2d4+2"}',NULL,'potion'),
('potion_healing_greater','Greater Potion of Healing','A deeper red than the common draught, and it moves on its own. Restores 4d4+4 hit points.','potion','uncommon',0.5,150,NULL,NULL,NULL,NULL,NULL,'{"heals":"4d4+4"}',NULL,'potion'),
('priory_cartulary','The Arden Cartulary, Fourth Press','One decade of a small house''s deeds, grants, boundaries and accounts, bound in order and dusted every week for a hundred and forty years. Old paper, in the estimate of the man who was buying it.','misc','rare',8,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('quarry_writ','Reeve''s Writ of Carriage','A grain factor''s writ, signed and sealed, permitting one wagon to pass the east gate unsearched.','misc','uncommon',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('quarterstaff','Quarterstaff','A walking stick that has been in more fights than most swords.','weapon','common',4,1,'1d6','bludgeoning',NULL,NULL,NULL,'{"versatile":"1d8","simple":true}',NULL,'weapon'),
('ring_of_protection','Ring of Protection','A plain band of grey metal, warm to the touch. The world''s edges land a little softer on whoever wears it.','misc','rare',0,600,NULL,NULL,NULL,NULL,'ring','{"ac_bonus":1,"save_bonus":1}',NULL,'treasure'),
('ropewalk_line','Ropewalk Line','Fifty feet of three-strand hemp laid in the Ropehouse, which is to say laid properly: even, dry, and softer in the hand than rope has any business being. Waerhaven''s one genuinely famous export, and the only thing the Moot has never once been accused of shorting anybody on.','misc','common',8,12,NULL,NULL,NULL,NULL,NULL,'{"climb_advantage":true}',NULL,'misc'),
('scroll_of_mending_flesh','Scroll of Mending Flesh','A Priory copyist''s rendering of Cure Wounds, good for one reading. The vellum crumbles as the last word lands.','scroll','uncommon',0.1,120,NULL,NULL,NULL,NULL,NULL,'{"use_effect":{"cast":"cure_wounds"}}',NULL,'scroll'),
('shield_warded','Warded Shield','A round shield with a prayer of the Priory hammered into the boss in old letters. Blows seem to arrive a little off-true.','armor','uncommon',6,250,NULL,NULL,2,'shield',NULL,'{"ac_bonus":1}',NULL,'armor'),
('shortbow','Shortbow','Hill yew, strung with gut. The grip is worn to the shape of one hand.','weapon','common',2,25,'1d6','piercing',NULL,NULL,NULL,'{"ranged":"80/320","two_handed":true,"simple":true}',NULL,'bow'),
('shortsword','Shortsword','A short straight blade, worn low and drawn fast.','weapon','common',2,10,'1d6','piercing',NULL,NULL,NULL,'{"finesse":true,"light":true,"martial":true}',NULL,'sword'),
('silvered_shortsword','Silvered Shortsword','A light blade sheathed in silver, kept for the things steel does not trouble.','weapon','uncommon',2,110,'1d6','piercing',NULL,NULL,NULL,'{"finesse":true,"light":true,"silvered":true,"martial":true}',NULL,'sword'),
('sling','Sling','Two cords and a leather cradle. Ammunition is whatever the road is made of.','weapon','common',0,1,'1d4','bludgeoning',NULL,NULL,NULL,'{"ranged":"30/120","simple":true}',NULL,'weapon'),
('sluice_ledger','The Sluice-Keeper''s Quarters','Forty years of quarterly wages, recorded by a man who cannot write and keeps his accounts in notches and coin-rubbings. Every quarter paid, none of them late, and not one name anywhere in it.','misc','uncommon',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('spear','Spear','Ash haft, leaf blade. Held in one hand behind a shield or in two without.','weapon','common',3,1,'1d6','piercing',NULL,NULL,NULL,'{"versatile":"1d8","thrown":"20/60","simple":true}',NULL,'weapon'),
('surveyors_plumb','Brass Plumb-Bob','A surveyor''s bob on eighteen inches of waxed line, the brass worn bright at the shoulder. The maker''s stamp on the flat is a plumb-bob hanging inside a square. It is a perfectly ordinary tool and there is nothing whatever wrong with it.','misc','common',1,4,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'amulet'),
('tarrow_bread_token','Tarrow Bread Token','A stamped tin disc that buys one loaf at the Oakum House cart, issued in place of wages, redeemable only from the Houses, and worth precisely what Mother Reth says it is worth on the day. There are more of these in circulation in Tarrow than there are coins.','misc','common',0.05,1,NULL,NULL,NULL,NULL,NULL,'{"currency_token":true}',NULL,'coin'),
('the_ledger','The Mill Ledger','Two years of grain tallies in one careful hand. Six caravans are entered twice and paid once.','misc','uncommon',3,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('the_tenth_hull','Lines of a Tenth Hull','Sheer, half-breadth and body plan of a vessel the Moot has no class for: shorter than a fleet hull, far deeper, double-framed forward and sheathed to the wale in a way that only makes sense against ice. Drawn at night by somebody who has never been given a drawing board of their own.','misc','rare',0.3,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('the_valley_survey','The Valley Survey','Nine sheets of good paper, rolled, tied and unlocked: every field, road, weir, seam and roof between the ford and Greyhythe, measured, valued and totalled. Rivermark is on sheet six. It is not drawn as a town. It is entered in the margin as a cost, against the head ''clearance'', with a figure beside it and the figure has been revised downward twice.','misc','rare',2,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('thieves_tools','Thieves'' Tools','Picks, a small file, a mirror on a wire. Sera keeps them in a flour tin.','misc','common',1,25,NULL,NULL,NULL,NULL,NULL,'{"tool":"thieves_tools"}',NULL,'tools'),
('truce_token','Warlord''s Tooth','A bugbear''s tooth drilled and hung on wire. In the warren it means the bearer is not to be eaten.','misc','uncommon',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"safe_passage":"warren"}',NULL,'amulet'),
('uv_cracked_lamp','Cracked Delving Lamp','The gauze is split down one side and the brass is dented half round, which is why it came up the hill in a spoil basket instead of on a belt. It still lights, and it still burns the eleven hours it was made to burn.','misc','common',3,6,NULL,NULL,NULL,NULL,NULL,'{"light":true}',NULL,'lantern'),
('uv_crew_tag','Kell''s Crew Tag','A lead disc stamped with a crew number and a letter, on a bootlace. Every delver carries two of them, so that whoever comes up can leave one and whoever does not can be counted. Dessa Kell has had this one on the table eleven weeks.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true}',NULL,'misc'),
('uv_delvers_pick','Delver''s Pick','A short pick with a hardened point and a shaft cut down to swing in a passage where a full one would foul the roof. Thrown on the heap for a cracked eye, which somebody has since bound with wire and thrown away again.','weapon','common',4,5,'1d6','piercing',NULL,NULL,NULL,'{"simple":true}',NULL,'weapon'),
('uv_knotted_rag','A Knotted Rag','Coin in the corner of a sleeve, knotted twice and knotted again, the way a man carries money he does not want to hear. It went into the spoil basket inside whatever it was in the pocket of.','treasure','common',0,14,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'coin'),
('vorns_list','Warden Vorn''s List','Sixty names in one hand, with the village each came out of and the day they left it, and forty-one of them ticked. The nineteen that are not ticked have a mark against them instead, and the mark is the same mark nineteen times, and it is not a cross.','misc','rare',0.2,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book'),
('wages_note','Note of Hand for Wages','Fourteen days at one and threepence, drawn on the Rivermark counting house and payable by a house downriver whose name is written only as initials and a mark: a plumb-bob hanging inside a square.','misc','common',0,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'scroll'),
('wardens_cloak','Warden''s Oilcloth','Green wax-cloth cut for the eastern hills. It has been patched at the left shoulder twice.','armor','uncommon',3,120,NULL,NULL,0,'cloak',NULL,'{"stealth_advantage_outdoors":true}',NULL,'cloak'),
('wardens_tally','The Warden''s Tally','Two years of counting in a waxed-thread book, one line per day, no words. Ilse Thornwood''s hand throughout. Read forwards it is a warning; read backwards it is something else.','misc','uncommon',1,0,NULL,NULL,NULL,NULL,NULL,'{"quest_item":true,"readable":true}',NULL,'book')
INSERT INTO monsters (monster_key,name,size,type,alignment,armor_class,hit_points,hit_dice,speed,strength,dexterity,constitution,intelligence,wisdom,charisma,challenge_rating,experience_points,traits,actions,legendary_actions,saves_json,resistances_json,immunities_json,vulnerabilities_json,condition_immunities_json,loot_json,rank_pref,image_url,sprite_key,source) VALUES
('bandit','Bandit','Medium','humanoid (any race)','any non-lawful alignment',12,11,'2d8+2','30 ft.',11,12,12,10,10,10,0.125,25,'{}','[{"name":"Scimitar","type":"melee","bonus":3,"damage":"1d6+1","damage_type":"slashing"},{"name":"Light Crossbow","type":"ranged","bonus":3,"damage":"1d8+1","damage_type":"piercing","range":"80/320"}]',NULL,'{"dex":1}','[]','[]','[]','[]','[{"gold":"2d6"},{"item":"leather_armor","chance":15}]','front','assets/images/monsters/bandit.png','bandit','5e SRD'),
('bog_crawler','Bog Crawler','Medium','beast','unaligned',13,22,'4d8+4','20 ft., swim 30 ft.',13,14,13,2,10,4,1,200,'{"Peat-Blind":"The crawler hunts by pressure in the water and is not troubled by darkness or by mist.","Amphibious":"It can breathe air and water."}','[{"name":"Claws","type":"melee","bonus":4,"damage":"1d8+2","damage_type":"slashing"},{"name":"Drag Under","type":"melee","bonus":4,"damage":"1d6+2","damage_type":"bludgeoning","note":"On a hit against a target standing in water, the target must succeed on a DC 12 Strength save or be knocked prone.","save":{"ability":"str","dc":12},"on_fail":{"condition":"prone","rounds":1}}]',NULL,'{"str":3}','["poison"]','[]','[]','["prone"]','[{"item":"fen_root_bundle","chance":30}]','front','assets/images/monsters/bog_crawler.png','bog_crawler','Rivermark'),
('broodmother_spider','Broodmother','Large','beast','unaligned',15,58,'9d10+9','30 ft., climb 30 ft.',16,16,13,3,12,4,3,700,'{"Spider Climb":"The broodmother can climb difficult surfaces, including upside down on ceilings, without needing an ability check.","Web Sense":"While in contact with a web, she knows the exact location of any other creature in contact with the same web.","Web Walker":"She ignores movement restrictions caused by webbing.","Drop From Above":"She has advantage on attack rolls against any creature that has not yet acted this combat."}','[{"name":"Bite","type":"melee","bonus":6,"damage":"2d8+3","damage_type":"piercing","note":"The target must make a DC 13 Constitution saving throw, taking 3d8 poison damage on a failure, or half as much on a success.","save":{"ability":"con","dc":13},"on_fail":{"condition":"poisoned","rounds":10,"repeat_save":true}},{"name":"Web","type":"ranged","bonus":6,"damage":"0","damage_type":"bludgeoning","range":"30/60","note":"The target is wrapped and hauled toward the dark. As an action, the restrained target can make a DC 14 Strength check to tear free.","save":{"ability":"str","dc":14},"on_fail":{"condition":"restrained","repeat_save":true}}]',NULL,'{"dex":6,"con":4}','[]','[]','[]','[]','[{"gold":"2d10"},{"item":"cloak_of_the_marsh","chance":50}]','front','assets/images/monsters/broodmother_spider.png','broodmother_spider','5e SRD'),
('bugbear','Bugbear','Medium','humanoid (goblinoid)','chaotic evil',16,27,'5d8+5','30 ft.',15,14,13,8,11,9,1,200,'{"Brute":"A melee weapon deals one extra die of its damage when the bugbear hits with it (included in the attack).","Surprise Attack":"If the bugbear surprises a creature and hits it with an attack during the first round of combat, the attack deals an extra 2d6 damage."}','[{"name":"Morningstar","type":"melee","bonus":4,"damage":"2d8+2","damage_type":"piercing"},{"name":"Javelin","type":"ranged","bonus":4,"damage":"1d6+2","damage_type":"piercing","range":"30/120"}]',NULL,'{"dex":2}','[]','[]','[]','[]','[{"gold":"3d6"},{"item":"oil_of_embers","chance":25}]','front','assets/images/monsters/bugbear.png','bugbear','5e SRD'),
('carrion_crawler','Carrion Crawler','Large','monstrosity','unaligned',13,51,'6d10+18','30 ft., climb 30 ft.',14,13,16,1,12,5,2,450,'{"Keen Smell":"The crawler has advantage on Wisdom (Perception) checks that rely on smell.","Spider Climb":"The crawler can climb difficult surfaces, including upside down on ceilings, without needing an ability check."}','[{"name":"Tentacles","type":"melee","bonus":8,"damage":"1d4+2","damage_type":"poison","note":"The target must succeed on a DC 13 Constitution saving throw or be poisoned for 1 minute. Until this poison ends, the target is paralysed.","save":{"ability":"con","dc":13},"on_fail":{"condition":"paralyzed","rounds":10,"repeat_save":true}},{"name":"Bite","type":"melee","bonus":4,"damage":"2d4+2","damage_type":"piercing"}]',NULL,'{}','[]','[]','[]','[]','[{"item":"antitoxin","chance":40}]','front','assets/images/monsters/crawler.png','crawler','5e SRD'),
('city_engineer','City Engineer','Medium','humanoid (any race)','neutral',10,4,'1d8','30 ft.',10,10,10,10,10,10,0,10,'{}','[{"name":"Mattock","type":"melee","bonus":2,"damage":"1d4","damage_type":"bludgeoning"}]',NULL,'{}','[]','[]','[]','[]','[{"gold":"1d6"},{"item":"surveyors_plumb","chance":35}]','front','assets/images/monsters/city_engineer.png','city_engineer','5e SRD'),
('city_guard','City Guard','Medium','humanoid (any race)','lawful neutral',16,11,'2d8+2','30 ft.',13,12,12,10,11,10,0.125,25,'{}','[{"name":"Spear","type":"melee","bonus":3,"damage":"1d6+1","damage_type":"piercing"},{"name":"Light Crossbow","type":"ranged","bonus":3,"damage":"1d8+1","damage_type":"piercing","range":"80/320"}]',NULL,'{}','[]','[]','[]','[]','[{"gold":"2d6"},{"item":"oldcity_steel_helm","chance":20}]','front','assets/images/monsters/city_guard.png','city_guard','5e SRD'),
('concern_warden','Pit Warden','Medium','humanoid (human)','lawful neutral',14,22,'4d8+4','30 ft.',13,13,13,10,11,10,1,200,'{"Paid Weekly":"Wardens do not rout while a serjeant of the works is standing. It is in the terms."}','[{"name":"Weighted Baton","type":"melee","bonus":4,"damage":"1d8+2","damage_type":"bludgeoning"},{"name":"Crossbow","type":"ranged","bonus":4,"damage":"1d8+1","damage_type":"piercing","range":"80/320"}]',NULL,'{}','[]','[]','[]','[]','[{"gold":"3d6"},{"item":"pit_belt","chance":25}]','front','assets/images/monsters/concern_warden.png','concern_warden','Rivermark Chronicles'),
('crust','Crust','Medium','elemental','unaligned',16,40,'6d8+12','20 ft.',17,8,15,3,8,3,2,450,'{"Wrong Stone":"The diggers'' word for it, and the only word anybody down here uses. Takes half damage from picks, hammers and anything else the works issues."}','[{"name":"Slam","type":"melee","bonus":5,"damage":"2d6+3","damage_type":"bludgeoning"}]',NULL,'{"con":4}','["piercing","slashing"]','["poison"]','["thunder"]','["poisoned","charmed","frightened"]','[{"gold":"2d10"},{"item":"marked_pauldron","chance":30}]','front','assets/images/monsters/rock_man.png','rock_man','Rivermark Chronicles'),
('deep_gremlin','Deep Gremlin','Small','monstrosity','unaligned',13,14,'4d6','30 ft., climb 30 ft.',9,16,11,6,10,5,0.5,100,'{"Came Up the Hole":"Gremlins do not den in the warren. Every one of them has come up from below in the last two years, and they come up in numbers when the cutting below is loud.","Sunlight Sensitivity":"Disadvantage on attack rolls and on Perception checks relying on sight in sunlight."}','[{"name":"Claws","type":"melee","bonus":5,"damage":"1d6+3","damage_type":"slashing"},{"name":"Thrown Stone","type":"ranged","bonus":5,"damage":"1d4+3","damage_type":"bludgeoning"}]',NULL,'{"dex":5}','[]','[]','[]','[]','[{"gold":"2d4","chance":60},{"item":"uv_delvers_pick","chance":25}]','front','assets/images/monsters/gremlin.png','gremlin','Rivermark'),
('dire_wolf','Dire Wolf','Large','beast','unaligned',14,37,'5d10+10','50 ft.',17,15,15,3,12,7,1,200,'{"Keen Hearing and Smell":"The wolf has advantage on Wisdom (Perception) checks that rely on hearing or smell.","Pack Tactics":"The wolf has advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 feet of the creature and that ally isn''t incapacitated."}','[{"name":"Bite","type":"melee","bonus":5,"damage":"2d6+3","damage_type":"piercing","note":"If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone.","save":{"ability":"str","dc":13},"on_fail":{"condition":"prone","rounds":1}}]',NULL,'{"dex":2}','[]','[]','[]','[]','[{"item":"dried_fen_root","chance":35}]','front','assets/images/monsters/dire_wolf.png','dire_wolf','5e SRD'),
('drowned_clerk','The Drowned Clerk','Medium','undead','neutral',12,45,'7d8+14','20 ft., swim 30 ft.',15,10,15,10,11,6,2,450,'{"Will Not Leave the Room":"The clerk does not pursue beyond the strongroom door. It has never once tried to.","Underwater Silence":"The clerk makes no sound at all, in or out of the water. It did not make much when it was living either.","Keeps the Boxes":"While any deposit box remains in the strongroom, the clerk has advantage on saving throws against being moved, charmed or frightened."}','[{"name":"Drag Down","type":"melee","bonus":4,"damage":"1d8+2","damage_type":"bludgeoning","note":"If the target is standing in the flooded room it must succeed on a DC 13 Strength saving throw or be pulled under and begin to drown, taking 1d6 at the start of each of its turns until it or an ally spends an action to get it up.","save":{"ability":"str","dc":13},"on_fail":{"condition":"restrained","repeat_save":true}},{"name":"Ledger Weight","type":"melee","bonus":4,"damage":"2d6+2","damage_type":"bludgeoning","note":"A brass-cornered ledger weight on a thong, still tied to its wrist."}]',NULL,'{"con":4}','["necrotic","bludgeoning, piercing and slashing from nonmagical attacks"]','["poison"]','[]','["exhaustion","frightened","poisoned"]','[{"gold":"2d8"},{"item":"oldcity_lockbox_purse","chance":35}]','front','assets/images/monsters/boss_drowned.png','boss_drowned','Rivermark Chronicles'),
('drowned_man','One of the Drowned','Medium','undead','neutral evil',12,52,'8d8+16','20 ft., swim 30 ft.',16,10,15,5,8,6,3,700,'{"Held by the Water":"Peat water does not let go of what it takes. Away from the fen it fails inside a day; in it, it does not fail at all.","Undead Fortitude":"If reduced to 0 hit points by damage other than radiant, it makes a DC 5 + damage Constitution save and drops to 1 hit point on a success."}','[{"name":"Grasp","type":"melee","bonus":5,"damage":"2d6+3","damage_type":"bludgeoning"},{"name":"Pull Down","type":"melee","bonus":5,"damage":"1d8+3","damage_type":"cold","note":"On a hit in water the target must make a DC 13 Strength save or be grappled and dragged under.","save":{"ability":"str","dc":13},"on_fail":{"condition":"grappled","repeat_save":true}}]',NULL,'{"con":4}','["necrotic"]','["poison"]','[]','["exhaustion","poisoned"]','[{"gold":"3d8"},{"item":"oldcity_silver_ring","chance":30}]','front','assets/images/monsters/drowned_man.png','drowned_man','Rivermark Chronicles'),
('fen_horror','Fen Horror','Large','aberration','unaligned',14,60,'8d10+16','10 ft., swim 40 ft.',17,14,15,3,12,5,3,700,'{"Peat-Held":"Peat water preserves what it takes. The horror has been in the black pools long enough to be part of them and does not leave the water willingly.","Hold Breath":"It can hold its breath for an hour."}','[{"name":"Tendril","type":"ranged","bonus":5,"damage":"1d10+3","damage_type":"bludgeoning","note":"Reach 15 ft. On a hit the target is grappled and pulled 10 feet toward the water."},{"name":"Bite","type":"melee","bonus":5,"damage":"2d8+3","damage_type":"piercing"}]',NULL,'{"con":4}','["cold"]','[]','["fire"]','["prone"]','[{"gold":"3d8"},{"item":"amulet_of_warding","chance":40}]','front','assets/images/monsters/tentacled.png','tentacled','Rivermark'),
('fen_howler','Fen Howler','Large','beast','unaligned',13,45,'6d10+12','40 ft.',18,13,15,4,13,6,2,450,'{"Drives the Herd":"Cattle and horses within sight of the howler will not stand. Herds bunch and face it, which is how drovers know it is there before they see it.","Keen Hearing":"Advantage on Wisdom (Perception) checks that rely on hearing."}','[{"name":"Bite","type":"melee","bonus":6,"damage":"2d8+4","damage_type":"piercing"},{"name":"Call","type":"melee","bonus":6,"damage":"1d6","damage_type":"thunder","note":"A flat carrying note rather than a howl. Anything within earshot that is not the howler''s own kind must succeed on a DC 12 Wisdom save or be frightened until the end of its next turn.","save":{"ability":"wis","dc":12},"on_fail":{"condition":"frightened","rounds":1}}]',NULL,'{"con":4}','[]','[]','[]','[]','[{"item":"fen_root_bundle","chance":40}]','front','assets/images/monsters/howler.png','howler','Rivermark'),
('giant_centipede','Giant Centipede','Small','beast','unaligned',13,9,'2d6+2','30 ft., climb 30 ft.',5,14,12,1,7,3,0.25,50,'{}','[{"name":"Bite","type":"melee","bonus":4,"damage":"1d4+2","damage_type":"piercing","note":"The target must make a DC 11 Constitution saving throw, taking 3d6 poison damage on a failure, or half as much on a success.","save":{"ability":"con","dc":11},"on_fail":{"condition":"poisoned","rounds":3,"repeat_save":true}}]',NULL,'{"dex":4}','[]','[]','[]','[]','[{"item":"antitoxin","chance":20}]','front','assets/images/monsters/giant_centipede.png','giant_centipede','5e SRD'),
('giant_rat','Giant Rat','Small','beast','unaligned',12,7,'2d6','30 ft.',7,15,11,2,10,4,0.125,25,'{"Keen Smell":"The rat has advantage on Wisdom (Perception) checks that rely on smell.","Pack Tactics":"The rat has advantage on an attack roll against a creature if at least one of the rat''s allies is within 5 feet of the creature and that ally isn''t incapacitated."}','[{"name":"Bite","type":"melee","bonus":4,"damage":"1d4+2","damage_type":"piercing"}]',NULL,'{"dex":2}','[]','[]','[]','[]','[{"item":"uv_knotted_rag","chance":20}]','front','assets/images/monsters/giant_rat.png','giant_rat','5e SRD'),
('giant_spider','Giant Spider','Large','beast','unaligned',14,26,'4d10+4','30 ft., climb 30 ft.',14,16,12,2,11,4,1,200,'{"Spider Climb":"The spider can climb difficult surfaces, including upside down on ceilings, without needing an ability check.","Web Sense":"While in contact with a web, the spider knows the exact location of any other creature in contact with the same web.","Web Walker":"The spider ignores movement restrictions caused by webbing."}','[{"name":"Bite","type":"melee","bonus":5,"damage":"1d8+3","damage_type":"piercing","note":"The target must make a DC 11 Constitution saving throw, taking 2d8 poison damage on a failure, or half as much on a success."},{"name":"Web","type":"ranged","bonus":5,"damage":"0","damage_type":"bludgeoning","range":"30/60","note":"The target is restrained by webbing. As an action, the restrained target can make a DC 12 Strength check, bursting the webbing on a success.","save":{"ability":"str","dc":12},"on_fail":{"condition":"restrained","repeat_save":true}}]',NULL,'{"dex":5}','[]','[]','[]','[]','[{"item":"antitoxin","chance":35}]','front','assets/images/monsters/giant_spider.png','giant_spider','5e SRD'),
('giant_toad','Giant Toad','Large','beast','unaligned',11,39,'6d10+6','20 ft., swim 40 ft.',15,13,13,2,10,3,1,200,'{"Amphibious":"The toad can breathe air and water."}','[{"name":"Bite","type":"melee","bonus":4,"damage":"1d10+2","damage_type":"piercing","note":"Plus 1d10 poison damage. The target is grappled (escape DC 13) and restrained, and the toad cannot bite another target while it holds one.","save":{"ability":"str","dc":13},"on_fail":{"condition":"grappled","repeat_save":true}}]',NULL,'{"str":4}','[]','[]','[]','[]','[{"item":"antitoxin","chance":25}]','front','assets/images/monsters/giant_toad.png','giant_toad','5e SRD'),
('gnoll','Gnoll','Medium','humanoid (gnoll)','chaotic evil',15,22,'5d8','30 ft.',14,12,11,6,10,7,0.5,100,'{"Rampage":"When the gnoll reduces a creature to 0 hit points with a melee attack on its turn, the gnoll can take a bonus action to move up to half its speed and make a bite attack."}','[{"name":"Bite","type":"melee","bonus":4,"damage":"1d4+2","damage_type":"piercing"},{"name":"Spear","type":"melee","bonus":4,"damage":"1d6+2","damage_type":"piercing","note":"1d8+2 when used with two hands."},{"name":"Longbow","type":"ranged","bonus":3,"damage":"1d8+1","damage_type":"piercing","range":"150/600"}]',NULL,'{"dex":1}','[]','[]','[]','[]','[{"gold":"2d6"},{"item":"javelin","chance":30}]','front','assets/images/monsters/gnoll.png','gnoll','5e SRD'),
('goblin','Goblin','Small','humanoid (goblinoid)','neutral evil',15,7,'2d6','30 ft.',8,14,10,10,8,8,0.25,50,'{"Nimble Escape":"The goblin can take the Disengage or Hide action as a bonus action on each of its turns."}','[{"name":"Scimitar","type":"melee","bonus":4,"damage":"1d6+2","damage_type":"slashing"},{"name":"Shortbow","type":"ranged","bonus":4,"damage":"1d6+2","damage_type":"piercing","range":"80/320"}]',NULL,'{"dex":2}','[]','[]','[]','[]','[{"gold":"1d6","chance":60},{"item":"shortsword","chance":15}]','front','assets/images/monsters/goblin.png','goblin','5e SRD'),
('grey_ooze','Grey Ooze','Medium','ooze','unaligned',8,22,'3d8+9','10 ft., climb 10 ft.',12,6,16,1,6,2,0.5,100,'{"Amorphous":"The ooze can move through a space as narrow as 1 inch wide without squeezing.","Corrode Metal":"Any nonmagical weapon made of metal that hits the ooze corrodes. After dealing damage, the weapon takes a permanent and cumulative -1 penalty to damage rolls. If its penalty drops to -5, the weapon is destroyed.","False Appearance":"While the ooze remains motionless, it is indistinguishable from an oily pool or wet rock."}','[{"name":"Pseudopod","type":"melee","bonus":3,"damage":"1d6+1","damage_type":"bludgeoning","note":"Plus 2d6 acid damage, and if the target is wearing nonmagical metal armour, its armour is partly corroded and takes a permanent and cumulative -1 penalty to AC."}]',NULL,'{}','["acid","cold","fire"]','[]','[]','["blinded","charmed","deafened","exhaustion","frightened","prone"]','[{"gold":"2d10","chance":60},{"item":"shortsword","chance":20}]','front','assets/images/monsters/ooze.png','ooze','5e SRD'),
