('healing_word','Healing Word',1,'{"dice_per_level":"1d4"}','Evocation','1 bonus action','60 feet','V','Instantaneous','A creature of your choice that you can see within range regains hit points.','1d4',NULL,'heal',NULL,'half',0,0,'ally',1,NULL,'Bard,Cleric,Druid','5e SRD'),
('hellish_rebuke','Hellish Rebuke',1,'{"dice_per_level":"1d10"}','Evocation','1 reaction','60 feet','V, S','Instantaneous','You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. It must make a Dexterity saving throw, taking fire damage on a failed save, or half as much on a success.','2d10','fire','save','dex','half',0,0,'enemy',1,NULL,'Warlock','5e SRD'),
('hold_person','Hold Person',2,NULL,'Enchantment','1 action','60 feet','V, S, M','Concentration, up to 1 minute','Choose a humanoid that you can see within range. The target must succeed on a Wisdom saving throw or be paralyzed.',NULL,NULL,'debuff','wis','negate',1,10,'enemy',1,'{"condition":"paralyzed"}','Bard,Cleric,Druid,Sorcerer,Warlock,Wizard','5e SRD'),
('hunters_mark','Hunter''s Mark',1,NULL,'Divination','1 bonus action','90 feet','V','Concentration, up to 1 hour','You choose a creature you can see and mystically mark it as your quarry. You deal an extra 1d6 damage to your target whenever you hit it with a weapon attack.',NULL,NULL,'buff',NULL,'half',1,10,'self',1,'{"damage_bonus_dice":"1d6"}','Ranger','5e SRD'),
('hypnotic_pattern','Hypnotic Pattern',3,NULL,'Illusion','1 action','120 feet','S, M','Concentration, up to 1 minute','You create a twisting pattern of colours that weaves through the air. Each creature in the area that sees the pattern must make a Wisdom saving throw or become charmed and incapacitated.',NULL,NULL,'debuff','wis','negate',1,10,'all_enemies',1,'{"condition":"incapacitated"}','Bard,Sorcerer,Warlock,Wizard','5e SRD'),
