INSERT INTO encounters (encounter_key,name,description,location_id,region_id,is_random,is_ambush,difficulty,allow_flee,allow_parley,parley_node,victory_flag,defeat_flag,victory_quest_stage,scale_to_party) VALUES
('boom_press_gang','The Watch, Sober','Twelve of forty are sober before noon and Skeld has had the sense to send those twelve. They are not angry and they are not corrupt about this particular thing, which makes them considerably worse to be in a room with.',NULL,NULL,0,0,'medium',1,1,'oren_skeld:he_calls_it_off','watch_beaten',NULL,NULL,1),
('broken_floor_gremlins','Up Through the Floor','They come up the inside of the hole, hand over hand on cut stone, four of them, and they are not interested in the goblins at all.',(SELECT id FROM locations WHERE location_key = 'broken_floor'),NULL,0,1,'medium',1,0,NULL,'broken_floor_held',NULL,NULL,1),
('cellar_rats_swarm','Something in the Cellar','Four grey shapes come off the grain sacks at once. They are not frightened of light.',(SELECT id FROM locations WHERE location_key = 'flagon_cellar'),NULL,0,1,'easy',1,0,NULL,'cellar_rats_beaten',NULL,NULL,1),
('cellar_stirges','The Sump Behind the Wall','The rats were eating what came up the drain. The drain still has things in it.',(SELECT id FROM locations WHERE location_key = 'flagon_cellar'),NULL,0,0,'easy',1,0,NULL,'cellar_stirges_beaten',NULL,NULL,1),
('charter_men','The Second Door','The bolted door was bolted from the other side, and the other side has been listening. There are two chairs in this room and there were always going to be more people than that — and none of them are League, and none of them are Watch, and every one of them is being paid by somebody who cannot afford to be named in a court.',(SELECT id FROM locations WHERE location_key = 'the_quiet_charter'),NULL,0,1,'hard',1,0,NULL,'charter_men_beaten',NULL,NULL,1),
('conduit_crawler','What Was Lifting the Gratings','It comes off the crown of the vault, where it has been the whole time, in the one direction nobody carries a lamp.',(SELECT id FROM locations WHERE location_key = 'low_conduit'),NULL,0,0,'hard',1,0,NULL,'conduit_crawler_beaten',NULL,NULL,1),
('deep_shaft','What Came Up the Shaft','Whatever is below sends its leavings up. These reached the ledge first.',(SELECT id FROM locations WHERE location_key = 'deep_shaft'),NULL,0,0,'deadly',1,0,NULL,'deep_shaft_cleared',NULL,NULL,1),
('deepworks_shift','Between Lamps','Something in the dark between two lamps that the shift has learned to walk around, and which the shift is not walking around today.',NULL,(SELECT id FROM regions WHERE region_key = 'the_deepworks'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('fen_crawl','Something Under the Withies','The water on the left of the causeway changes shape twice and then stops pretending.',NULL,(SELECT id FROM regions WHERE region_key = 'hollow_fen'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('fen_stirges','Off the Reed Bank','They come off the reeds in a body, low and fast, and the fen is the only place in the valley where there are enough of them to matter.',NULL,(SELECT id FROM regions WHERE region_key = 'hollow_fen'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('ford_road_gang','Three Off the Road','Men in the hedge who were carters last season and have found that the west road is quieter than it used to be.',NULL,(SELECT id FROM regions WHERE region_key = 'ford_road'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('ford_road_strays','Off the Winter Field','Two grey shapes working the hedge line, out of the common grazing and onto the road, hungrier than they were last month.',NULL,(SELECT id FROM regions WHERE region_key = 'ford_road'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('gaol_turnkeys','On Nobody''s Authority','The Tar Gaol is kept by the Houses on a warrant no court has ever seen, which means the men keeping it have thought harder than most about what happens to them if the arrangement ever ends. They are thinking about it now.',NULL,NULL,0,0,'hard',1,0,NULL,'gaol_opened',NULL,NULL,1),
('garrow_collectors','Collection Day','Three of Garrow Finch''s people, who have been paid to be unhurried about it.',(SELECT id FROM locations WHERE location_key = 'flagon_common_room'),NULL,0,0,'medium',0,1,'garrow_finch:call_them_off',NULL,NULL,NULL,1),
('goblin_scouts','Goblin Scouts','Two goblin sentries step off the quarry trail with their bows already up.',(SELECT id FROM locations WHERE location_key = 'quarry_road'),NULL,0,0,'easy',1,1,'nakka:scouts_hold',NULL,NULL,NULL,1),
('granary_knives','Knives at the Granary Door','Hollis Marrow does not fight. He employs two men and a dog who will.',(SELECT id FROM locations WHERE location_key = 'granary_row'),NULL,0,0,'medium',1,0,NULL,'granary_knives_beaten',NULL,NULL,1),
('hills_raiders','The Raiders on the Road','Two gnolls work the horses. The goblins go straight for the tailgate and the grain.',(SELECT id FROM locations WHERE location_key = 'broken_hills'),NULL,0,1,'hard',1,1,'nakka:raid_halt','hills_raiders_beaten',NULL,'teeth_in_the_hills:ambushed_the_raiders',1),
('low_court_bailiffs','The Court Rises','Nobody draws steel. Four of them put themselves between you and the passage north, the way people do when they have agreed beforehand who stands where.',(SELECT id FROM locations WHERE location_key = 'low_court'),NULL,0,0,'medium',1,1,'aggie_slate:sit_down_again',NULL,NULL,'the_undertown_court:refused_the_court',1),
('mast_pond_drowned','Under the Masts','A log rolls where no log should roll, and the black water lets go of something that has been down there among the seasoning pines rather longer than two years.',(SELECT id FROM locations WHERE location_key = 'the_mast_pond'),NULL,0,1,'medium',1,0,NULL,'mast_pond_beaten',NULL,'nine_masts:the_dry_dock',1),
('mill_race_vermin','The Wheel-Pit','Four years of grain-dust in a stone pit full of black water, and everything that has been living off it comes up the wall at once.',NULL,NULL,0,0,'medium',1,0,NULL,'mill_pit_cleared',NULL,NULL,1),
('oldcity_broodmother','The Broodmother','The webs move all at once in every direction, and then she is simply there, between you and the way back.',(SELECT id FROM locations WHERE location_key = 'oldcity_spider_lair'),NULL,0,1,'deadly',1,0,NULL,'oldcity_broodmother_down',NULL,'oldcity_the_cutters_trove:opened_the_workshop',1),
('oldcity_centipede_nest','The Nest In The Renegade','The corpse moves, and goes on moving after you have understood why.',(SELECT id FROM locations WHERE location_key = 'oldcity_renegades_stash'),NULL,0,1,'medium',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_goblin_gate','The Goblin Foothold','Ten of them, behind a rubble wall with a firing gap cut at the wrong height, all shouting at once.',(SELECT id FROM locations WHERE location_key = 'oldcity_goblin_foothold'),NULL,0,1,'hard',1,0,NULL,'oldcity_goblins_broken',NULL,NULL,1),
('oldcity_the_cook_pot','The Cook-Pot','He does not shout and he does not charge. He picks up the mace, and the warg gets off its haunches, and the two of them come at you together because they have done this before.',(SELECT id FROM locations WHERE location_key = 'oldcity_ogres_lair'),NULL,0,1,'deadly',1,0,NULL,'oldcity_ogre_down',NULL,NULL,1),
('oldcity_toad_pool','What Is In The Pool','The skin on the water breaks in one piece, which means it was never a skin.',(SELECT id FROM locations WHERE location_key = 'oldcity_toads_grotto'),NULL,0,1,'medium',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_centipedes','Out Of The Wall','They come out of a joint in the old stonework in a rope, one behind another, and keep coming.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_engineers','Surveying, Apparently','Four Works men with a rule and a lamp, a long way from any shoring, and none of them can say whose gang they are on.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_goblins','A Goblin Scouting Party','Five of them, arguing, until one of them sees you and the argument resolves itself.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_guard','A Patrol On The Causeway','Lamps coming the other way along the ledge, and a voice telling you to stand where you are.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_rats','The Channel Rats','The ledge ahead is moving, and it is moving toward you.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_spiders','Down From The Ceiling','One line of silk, then three more, and they are between you and the lit ground.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_thieves','A Crew Coming Back','Four of them along the wall-top with a sack between two, on their way home and not pleased to be seen doing it.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_wandering_wights','Tormented Of The Old City','Three figures standing in a doorway at the wrong height, in clothes three hundred years out of fashion, waiting for the street to be the way they remember it.',NULL,(SELECT id FROM regions WHERE region_key = 'old_city'),1,0,'deadly',1,0,NULL,NULL,NULL,NULL,1),
('oldcity_web_gate','The Web Gate','Four of them come down the sheets at once, from four different recesses, in complete silence.',(SELECT id FROM locations WHERE location_key = 'oldcity_spider_ante'),NULL,0,1,'hard',1,0,NULL,NULL,NULL,NULL,1),
('pit_bout_champion','The Pit''s Man','He comes down the ladder rather than out of the gate, because he is not what is kept behind the gate. The sand has been raked. The crowd has already been paid its money either way.',NULL,NULL,0,0,'hard',0,1,'orm_lisser:mid_bout','pit_champion_beaten','pit_champion_lost',NULL,1),
('pit_gate_beast','Whatever Is Behind the Gate','The rope goes up, the counterweight drops, and the thing that has been leaning on the boards for an hour comes out into the light already moving.',NULL,NULL,0,0,'hard',0,0,NULL,'pit_gate_beaten',NULL,NULL,1),
('pool_horror','What the Peat Kept','Fifteen feet of tendril comes out of black water that a pole cannot find the bottom of, and it does not come far out, because it does not have to.',(SELECT id FROM locations WHERE location_key = 'black_pools'),NULL,0,1,'hard',1,0,NULL,'black_pools_cleared',NULL,NULL,1),
('pump_gallery_crawlers','Out of the Launder','The pump crew''s sticks are stacked by the door because the pump crew are not here. Three long pale shapes come up out of the launder in the order they always come up in.',(SELECT id FROM locations WHERE location_key = 'pump_gallery'),NULL,0,1,'medium',1,0,NULL,'pump_gallery_cleared',NULL,NULL,1),
('quarry_trail_ambush','Ambush on the Quarry Trail','Slings first, then the ones with knives come down off the spoil heap.',(SELECT id FROM locations WHERE location_key = 'warren_approach'),NULL,0,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('reliquary_agents','The Buyer''s Men','Three men in good coats who have been waiting in the chapel through two offices, and who put the coats down before they start, because the coats cost more than the fight will.',NULL,NULL,0,0,'medium',1,0,NULL,'reliquary_agents_beaten',NULL,NULL,1),
('rest_cellar_rats','Up the Drain','They come out from behind the barrels in the flat, unhurried way of animals that have not been disturbed here before and have no reason to think they are about to be.',(SELECT id FROM locations WHERE location_key = 'the_rest_cellar'),NULL,0,1,'easy',1,0,NULL,'cellar_rats_beaten',NULL,NULL,1),
('root_bed_ooze','The Fourth Bed','Nothing about the fourth bed looks different, and that is because the thing in it has been the colour of the fourth bed for two seasons.',NULL,NULL,0,0,'medium',1,0,NULL,'root_beds_cleared',NULL,NULL,1),
('salt_wagon_knives','The Carters Object','The six men on the caravan ground stop being carters between one step and the next, which is a thing carters cannot usually do.',NULL,NULL,0,0,'medium',1,1,'hesk_dray:call_them_off','salt_wagons_taken',NULL,NULL,1),
('stilt_camp_stand','The Planks Come Down','Six platforms, seven people, and every plank walk between them pulled up in about four seconds. They have practised this against the watch and it works just as well against you.',NULL,NULL,0,0,'hard',1,1,'nesh_gray:stand_down','stilt_camp_taken','stilt_camp_lost',NULL,1),
('strongroom_clerk','Still at the Desk','Something stands up out of the silt between you and the racks, unhurried, with a brass-cornered ledger weight still tied to its wrist.',(SELECT id FROM locations WHERE location_key = 'drowned_counting_room'),NULL,0,1,'hard',1,0,NULL,'strongroom_cleared',NULL,'what_the_water_left:the_boxes',1),
('sump_drain_rats','The Rats'' Road','The gap behind the Flagon''s north wall is a road, and the traffic on it does not care for the lamp.',(SELECT id FROM locations WHERE location_key = 'sump_drain'),NULL,0,1,'easy',1,0,NULL,'sump_rats_beaten',NULL,NULL,1),
('tarrow_bravos','The Houses Answer','Nobody raises a voice. Mother Reth goes on skimming the near cauldron, and the gate is shut behind you by somebody you did not see arrive, and three men come off the fence with the unhurried competence of people paid by the week.',NULL,NULL,0,0,'hard',1,1,'mother_reth:she_calls_them_off','tarrow_bravos_beaten',NULL,NULL,1),
('the_drowned_nave','The Nave','Three feet of still black water in a stone room, and the still black water stands up.',NULL,NULL,0,0,'hard',1,0,NULL,'drowned_nave_cleared',NULL,NULL,1),
('the_drowned_ones','What Was Laid Out','The arrangement on the bottom of the drowned room is not an arrangement. It is a queue, and it has been waiting, and the water does not move even now.',(SELECT id FROM locations WHERE location_key = 'the_drowned_room'),NULL,0,1,'hard',1,0,NULL,'drowned_room_beaten',NULL,NULL,1),
('the_field_howler','What Came Up Off the Fen','It does not howl. It makes one flat carrying note, and two hundred acres of cattle go to the far hedge at once, and then it is in the open with you.',NULL,NULL,0,0,'hard',1,0,NULL,'howler_killed',NULL,NULL,1),
('the_light_men','On the Deep Side','The boat under the point has put four men on the rock, and they came up the keeper''s own stair, and they have done it often enough that not one of them puts a hand out for the rail.',NULL,NULL,0,0,'medium',1,0,NULL,'light_men_beaten',NULL,NULL,1),
('the_long_room_wardens','The Long Room','Nobody bars the door. Corse finishes the sentence he was in the middle of, and by the time he has finished it there are wardens between you and the front room.',NULL,NULL,0,0,'hard',1,0,NULL,'long_room_held','long_room_lost',NULL,1),
('the_office_wardens','The Ladder Cleared','Rourke does not shout. He leans out of the shutter and says a number, and the number is how many wardens come up the ladder behind you.',NULL,NULL,0,0,'hard',1,0,NULL,'office_taken','office_thrown_out',NULL,1),
('the_undercut_growth','The Face of the Cut','The face of the cut comes away in one piece, and what is behind it has been waiting for the last four inches for three years.',NULL,NULL,0,0,'deadly',1,0,NULL,'growth_cut_out','growth_drove_us_out',NULL,1),
('underquay_crawlers','Something in the Low Cellars','The water ahead of you stops being water in two places at once. Whatever lives down here has learned the tide, and the tide is what brings it food, and you have arrived on the tide.',(SELECT id FROM locations WHERE location_key = 'the_low_cellars'),NULL,0,1,'medium',1,0,NULL,'underquay_cleared',NULL,'the_carters_cellar:the_way_in_found',1),
('underquay_wandering_crawlers','Between the Plinths','Something pale comes over the brickwork sideways and stops when your light finds it, which is the wrong response and tells you it has been found before.',NULL,(SELECT id FROM regions WHERE region_key = 'the_underquay'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('underquay_wandering_rats','Off the Tide-mark','They come along the tide-mark in a line, at the height a rat swims, and they are not frightened of the light.',NULL,(SELECT id FROM regions WHERE region_key = 'the_underquay'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('undertown_prowl','Something Using the Same Ledge','The ledge is the only dry footing in a hundred yards, which means everything down here uses it, and two things using it are one thing too many.',NULL,(SELECT id FROM regions WHERE region_key = 'undertown'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('undertown_slick','The Wet Patch','There is a slick on the brick that your lamp went over twice on the way in, and it is not in the same place now.',NULL,(SELECT id FROM regions WHERE region_key = 'undertown'),1,0,'medium',1,0,NULL,NULL,NULL,NULL,1),
('warlord_hall','The Warlord''s Hall','Nakka Skarn puts her guard between herself and the door, and then draws anyway.',(SELECT id FROM locations WHERE location_key = 'warlord_hall'),NULL,0,1,'deadly',0,0,NULL,'warlord_hall_taken','warlord_hall_lost',NULL,1),
('warren_gate','The Warren Gate','A barricade of quarry timber, a bugbear behind it, and four goblins who have done this before.',(SELECT id FROM locations WHERE location_key = 'warren_mouth'),NULL,0,1,'hard',1,1,'nakka:gate_hail','warren_gate_forced',NULL,NULL,1),
('warren_stragglers','Warren Stragglers','A goblin rounds the tunnel bend with an armload of loot, sees you, and shrieks for its friend.',NULL,(SELECT id FROM regions WHERE region_key = 'goblin_warren'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('weir_gremlins','Toll at the Weir','Four of them on the ledge above the fall, with hooked poles, taking a very reasonable view of who owns anything a stranger is carrying past their pool.',(SELECT id FROM locations WHERE location_key = 'weir_chamber'),NULL,0,1,'medium',1,0,NULL,'weir_gremlins_beaten',NULL,NULL,1),
('wilds_wolves','Wolves on the Wind','Grey shapes slide out of the gorse on both sides of the path — a hunting pair, patient and thin.',NULL,(SELECT id FROM regions WHERE region_key = 'quarry_wilds'),1,0,'easy',1,0,NULL,NULL,NULL,NULL,1),
('winter_field_pack','The Thorn Brake','The herd has been facing this corner for three days. Coming out of the thorn: two big ones in front and two smaller behind, and all four of them thin.',(SELECT id FROM locations WHERE location_key = 'winter_field'),NULL,0,1,'hard',1,0,NULL,'winter_field_cleared',NULL,NULL,1)
